// Lọc công nợ quá hạn + dựng thông báo. TẤT ĐỊNH — không gọi LLM:
// danh sách nợ là con số, template cố định đủ rõ, không có gì để 'diễn giải'.
// (retail_debt_reminder gọi Brain viết lời vì nhắn TRỰC TIẾP cho khách nợ;
//  bản này chỉ báo NỘI BỘ cho chủ DN nên không cần.)
// Giờ VIỆT NAM (UTC+7): ngày UTC lệch một ngày trong 7 tiếng đầu ngày ở VN, làm
// khoản nợ đáo hạn hôm nay/hôm qua bị tính sai số ngày quá hạn.
const today = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json);
const vn = n => new Intl.NumberFormat('vi-VN').format(Number(n));

// NGÀY chỉ nhận ISO (YYYY-MM-DD, có thể kèm giờ), cùng luật với node "Ghép dữ liệu" của workflow báo giá. Bản trước so CHUỖI THÔ và đổi bằng new Date():
// ô kiểu DD/MM/YYYY (locale Việt Nam của Google Sheets) làm "31/12/2000" (quá hạn 26 năm) KHÔNG được báo, còn "15/07/2999" báo "quá hạn NaN ngày" (#265).
// Cố ý KHÔNG đoán DD/MM hay MM/DD: không đọc được thì trả null và đưa vào mục "không đọc được".
const ngayIso = v => {
  const k = /^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/.exec(String(v == null ? '' : v).trim());
  if (!k) return null;
  const y = +k[1], m = +k[2], d = +k[3];
  const t = new Date(Date.UTC(y, m - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) return null;
  return t.toISOString().slice(0, 10);
};
// SỐ TIỀN: số thật, chữ số thuần, hoặc dạng Việt Nam chấm phân cách nghìn ("4.550.000", có thể kèm đ/VND). Dạng khác ("4,55", "1e6", "bốn triệu") là null:
// Number("4.550.000") là NaN và làm khoản nợ BIẾN MẤT khỏi báo cáo, im lặng.
const soTien = v => {
  if (typeof v === 'number') return Number.isFinite(v) && v >= 0 ? v : null;
  const s = String(v == null ? '' : v).trim().replace(/\s*(đ|vnđ|vnd)$/i, '');
  if (/^\d{1,15}$/.test(s)) return Number(s);
  if (/^\d{1,3}(\.\d{3}){1,4}$/.test(s)) return Number(s.replace(/\./g, ''));
  return null;
};
const trong = v => v == null || String(v).trim() === '';
const maNgan = v => String(v == null ? '' : v).replace(/[^\w.\-]/g, '').slice(0, 24) || '(không mã)';

const overdue = [];
const khongDoc = [];
for (const r of rows) {
  if (!(r.status === 'open' || r.status === 'partial')) continue;
  if (trong(r.due_date)) continue;          // không có hạn: chưa thể quá hạn (giữ hành vi cũ)
  const han = ngayIso(r.due_date);
  const no = soTien(r.amount);
  const tra = trong(r.paid_amount) ? 0 : soTien(r.paid_amount);
  if (han === null || no === null || tra === null) {
    khongDoc.push(maNgan(r.quote_id));     // chỉ MÃ: không đưa nội dung ô lạ vào thông báo
    continue;
  }
  const con = no - tra;
  if (han < today && con > 0) {
    overdue.push({
      ...r, remaining: con, due_iso: han,
      days_late: Math.round((Date.parse(today) - Date.parse(han)) / 86400000)
    });
  }
}
overdue.sort((a, b) => b.days_late - a.days_late);

if (!overdue.length && !khongDoc.length) {
  return [{ json: { has_overdue: false, has_report: false } }];
}

const total = overdue.reduce((s, r) => s + r.remaining, 0);
const lines = overdue.map(r =>
  '• **' + r.customer_name + '** — còn nợ **' + vn(r.remaining) + ' đ**' +
  ', quá hạn ' + r.days_late + ' ngày (hạn ' + r.due_iso + ', mã ' + r.quote_id + ')'
);
let mo_ta = lines.join('\n');
if (khongDoc.length) {
  const ds = khongDoc.slice(0, 20).join(', ') + (khongDoc.length > 20 ? ', …' : '');
  mo_ta += (mo_ta ? '\n\n' : '') + '⚠️ **' + khongDoc.length + ' dòng không đọc được ngày hoặc số tiền** (ngày phải là YYYY-MM-DD, tiền là số hoặc 4.550.000): ' +
    ds + '. Sửa trong sheet Receivables rồi chờ lần nhắc sau; các dòng này CHƯA được tính vào danh sách trên.';
}
const tieu_de = overdue.length
  ? '💰 Công nợ quá hạn — ' + overdue.length + ' khách, tổng ' + vn(total) + ' đ' + (khongDoc.length ? ' (+' + khongDoc.length + ' dòng không đọc được)' : '')
  : '⚠️ Công nợ: ' + khongDoc.length + ' dòng không đọc được, chưa kiểm tra quá hạn được';

const body = { embeds: [{
  title: tieu_de,
  color: 15158332,
  description: mo_ta.slice(0, 3800),
  footer: { text: 'ANSER Logistics • nhắc mỗi thứ 2' },
  timestamp: new Date().toISOString()
}]};

return [{ json: { has_overdue: overdue.length > 0, has_report: true, discord_body: JSON.stringify(body) } }];
